package app.talklive.data

import android.content.Context
import app.talklive.R
import dagger.hilt.android.qualifiers.ApplicationContext
import org.json.JSONArray
import javax.inject.Inject
import javax.inject.Singleton

data class Icebreaker(val emoji: String, val text: String)

/**
 * The website's "break the ice" deck (res/raw/icebreakers.json, generated by
 * tools/gen-icebreakers.js). Drawn without repeats until every card was shown.
 */
@Singleton
class Icebreakers @Inject constructor(@ApplicationContext private val context: Context) {
    private val all: List<Icebreaker> by lazy {
        val arr = JSONArray(context.resources.openRawResource(R.raw.icebreakers).bufferedReader().use { it.readText() })
        (0 until arr.length()).map { arr.getJSONObject(it).let { o -> Icebreaker(o.getString("e"), o.getString("t")) } }
    }
    private val deck = ArrayDeque<Icebreaker>()

    @Synchronized
    fun draw(n: Int): List<Icebreaker> = List(n) {
        if (deck.isEmpty()) deck.addAll(all.shuffled())
        deck.removeFirst()
    }
}
